function draw({board,width,height,params}) {
  const C=VisualBook.palette, t=params.tau, zero=t/10, tail=(10-t)/20;
  const left=52, right=width-22;
  board.text('input-title','① 均匀取值',18,23,{size:16,weight:600});
  board.text('input-law','U(−10, 10)',right,23,{size:14,color:C.muted,anchor:'end'});
  const f=board.axes('before',{xDomain:[-10,10],yDomain:[0,0.1],xLabel:'初始值 u',yLabel:'密度',box:[left,59,right,143],grid:false});
  board.rect('input-area',f.x(-10),f.y(.05),f.x(10)-f.x(-10),f.y(0)-f.y(.05),C.blue,{opacity:.12});
  board.rect('removed-area',f.x(-t),f.y(.05),f.x(t)-f.x(-t),f.y(0)-f.y(.05),C.orange,{opacity:.25});
  board.curve('input-density',f,[[-10,.05],[10,.05]],{color:C.blue,width:2.5});
  board.text('threshold','|u| < '+t.toFixed(1)+' → 0',width/2,188,{size:15,color:C.orange,anchor:'middle'});
  board.text('output-title','② 阈值处理后',18,221,{size:16,weight:600});
  const g=board.axes('after',{xDomain:[-10,10],yDomain:[0,0.1],xLabel:'处理后 w′',yLabel:'密度',box:[left,253,right,337],grid:false});
  board.rect('left-area',g.x(-10),g.y(.05),g.x(-t)-g.x(-10),g.y(0)-g.y(.05),C.blue,{opacity:.12});
  board.rect('right-area',g.x(t),g.y(.05),g.x(10)-g.x(t),g.y(0)-g.y(.05),C.blue,{opacity:.12});
  board.curve('left-density',g,[[-10,.05],[-t,.05]],{color:C.blue,width:2.5});
  board.curve('right-density',g,[[t,.05],[10,.05]],{color:C.blue,width:2.5});
  board.curve('middle-density',g,[[-t,0],[t,0]],{color:C.orange,width:3});
  const yy=height-23;
  board.circle('atom',width/2-18,yy,12*Math.sqrt(zero),C.orange);
  board.text('atom-label','零点质量 '+(100*zero).toFixed(0)+'%',width/2+5,yy+5,{size:15,color:C.orange});
  board.text('left-mass',(100*tail).toFixed(0)+'%',left,yy+5,{size:15,color:C.blue});
  board.text('right-mass',(100*tail).toFixed(0)+'%',right,yy+5,{size:15,color:C.blue,anchor:'end'});
  return {threshold:t,initialDensity:.05,leftMass:tail,zeroMass:zero,rightMass:tail,totalMass:2*tail+zero,rule:'w′ = u if |u| ≥ τ else 0',distribution:'u ~ U(-10,10)',atomSymbol:'circle area proportional to zero probability, not density height'};
}
